function Write-AuditLog {
    param([string]$Status, [string]$Action, [string]$TargetUser, [string]$TargetApp, [string]$Detail)
    
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $currentUser = $env:USERNAME
    $hostName = $env:COMPUTERNAME
    
    # 1. Guardar log localmente
    if (-not (Test-Path $LOG_FOLDER)) { New-Item -ItemType Directory -Force -Path $LOG_FOLDER | Out-Null }
    $logLine = "[$timestamp] Host:$hostName | Ejecutor:$currentUser | Status:$Status | Accion:$Action | Objetivo:$TargetUser | App:$TargetApp | Detalle:$Detail"
    Add-Content -Path $LOG_FILE -Value $logLine

    # 2. Guardar log EN LÍNEA (Google Chat Módificado)
    if ($LOG_WEBHOOK_URL -ne "") {
        try {
            $messageText = "========== LOG EJECUCION RESET ==========`n" +
            "Status: $Status`n" +
            "Timestamp: $timestamp`n" +
            "Usuario: $currentUser`n" +
            "Host: $hostName`n" +
            "Action: $Action`n" +
            "TargetUser: $TargetUser`n" +
            "TargetApp: $TargetApp`n" +
            "Detail: $Detail"

            $payload = @{
                text = $messageText
            } | ConvertTo-Json

            $logClient = New-Object System.Net.WebClient
            $logClient.Headers.Add("Content-Type", "application/json; charset=utf-8")
            $logClient.UploadString($LOG_WEBHOOK_URL, "POST", $payload) | Out-Null
        }
        catch {
            # Si falla el envío online, no queremos que truene la aplicación
        }
    }
}

# ----------------------------------------------------------
# Componente Visual de Alertas (Custom Dialog)
# ----------------------------------------------------------
function Show-CustomAlert {
    param(
        [string]$Message,
        [string]$Title,
        [string]$Type = "Info"
    )
    
    $alertForm = New-Object System.Windows.Forms.Form
    $alertForm.Text = $Title
    $alertForm.Size = New-Object System.Drawing.Size(420, 220)
    $alertForm.StartPosition = "CenterParent"
    $alertForm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $alertForm.MaximizeBox = $false
    $alertForm.MinimizeBox = $false
    $alertForm.BackColor = [System.Drawing.ColorTranslator]::FromHtml("#F4F6F9")
    $alertForm.ShowIcon = $false
    
    $lblMsg = New-Object System.Windows.Forms.Label
    $lblMsg.Text = $Message
    $lblMsg.Font = New-Object System.Drawing.Font("Segoe UI", 10)
    $lblMsg.Location = New-Object System.Drawing.Point(20, 20)
    $lblMsg.Size = New-Object System.Drawing.Size(360, 90)
    $lblMsg.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    
    $btnColor = "#E20074"
    $lblMsg.ForeColor = [System.Drawing.Color]::Black
    if ($Type -eq "Error") { 
        $btnColor = "#D32F2F"
        $lblMsg.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    }
    elseif ($Type -eq "Warning") { 
        $btnColor = "#F57C00" 
    }
    elseif ($Type -eq "Success") { 
        $btnColor = "#388E3C"
        $lblMsg.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    }

    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Text = "Entendido"
    $btnOk.Size = New-Object System.Drawing.Size(140, 40)
    $btnOk.Location = New-Object System.Drawing.Point(130, 120)
    $btnOk.BackColor = [System.Drawing.ColorTranslator]::FromHtml($btnColor)
    $btnOk.ForeColor = [System.Drawing.Color]::White
    $btnOk.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnOk.FlatAppearance.BorderSize = 0
    $btnOk.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    $btnOk.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnOk.Add_Click({ $alertForm.Close() })

    $alertForm.Controls.Add($lblMsg)
    $alertForm.Controls.Add($btnOk)
    
    $alertForm.ShowDialog() | Out-Null
}

