# ----------------------------------------------------------
# Lógica API de UM: Lanzar y Polling
# ----------------------------------------------------------
$btnSubmit.Add_Click({
        # Validaciones básicas
        if ([string]::IsNullOrWhiteSpace($txtUsuario.Text) -or
            [string]::IsNullOrWhiteSpace($txtEmpleado.Text) -or
            [string]::IsNullOrWhiteSpace($txtCorreo.Text) -or
            $cmbApp.SelectedIndex -eq 0) {
            &$script:UpdateStatus "Por favor llena todos los campos necesarios." "Warning"
            return
        }

        $btnSubmit.Enabled = $false
        $btnSubmit.Text = "Procesando solicitud, por favor espera..."
        $gbDatos.Enabled = $false
        $gbSolicitud.Enabled = $false
        $progressBar.Value = 5
        $progressBar.Visible = $true
        $lblProgress.Text = "Preparando solicitud..."
        $lblProgress.Visible = $true
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        $form.Update()

        try {
            # Extra vars payload (Estructura de UM)
            $actionVal = if ($cmbAccion.SelectedItem -eq "Reinicio") { "RESETEO" } else { "DESBLOQUEO" }

            $BodyParams = @{
                action       = $actionVal
                curp         = "XXXX110101XXXXX11"
                employnumber = $txtEmpleado.Text
                mail         = $txtCorreo.Text
                rfc          = $txtRFC.Text
                source       = "voice"
                sysapp       = $cmbApp.SelectedItem
                user         = $txtUsuario.Text
            }
            $BodyJson = $BodyParams | ConvertTo-Json -Depth 2

            # Forzar TLS 1.2, deshabilitar Expect100Continue e IGNORAR errores de certificado SSL
            [System.Net.ServicePointManager]::Expect100Continue = $false
            [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12
            [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }

            $progressBar.Value = 20
            $lblProgress.Text = "Configurando conexión segura..."
            $form.Update()
        
            # Cliente web robusto (Invoke-RestMethod maneja mejor las conexiones)
            $headers = @{
                "Authorization" = "Bearer $UM_BEARER_TOKEN"
                "Content-Type"  = "application/json; charset=utf-8"
            }
        
            # 1. Llamar al API UM POST
            $launchUrl = "$UM_BASE_URL/RA/LIVERPOOL/setStarExecutionUM"

            $progressBar.Value = 35
            $lblProgress.Text = "Enviando solicitud al servidor UM..."
            $form.Update()
        
            $resp = Invoke-RestMethod -Uri $launchUrl -Method Post -Headers $headers -Body $BodyJson -UseBasicParsing
            $respText = $resp | ConvertTo-Json -Depth 10 -Compress
        
            # El endpoint POST de UM devuelve: { result: { idExecution: 1234 } }
            $jobId = $resp.result.idExecution

            if (-not $jobId) {
                throw "No se obtuvo 'idExecution' de UM. Respuesta: $respText"
            }

            # 2. Polling resultado de UM GET
            $completed = $false
        
            # Polling hasta ~80 segundos (10 * 8s)
            for ($i = 0; $i -lt 10; $i++) {
                
                # Actualizar barra de progreso (35% -> 90% en 10 intentos)
                $pollProgress = 35 + [math]::Floor(($i / 10) * 55)
                if ($pollProgress -gt 90) { $pollProgress = 90 }
                $progressBar.Value = $pollProgress
                $lblProgress.Text = [string]::Format("{0} Esperando respuesta del Robot Assistant... (intento {1}/10)", [char]0x23F3, ($i + 1))
                $form.Update()

                # Evitar que la UI se congele esperando usando DoEvents y sleeps pequeños
                $waitEndTime = (Get-Date).AddSeconds(8)
                while ((Get-Date) -lt $waitEndTime) {
                    [System.Windows.Forms.Application]::DoEvents()
                    Start-Sleep -Milliseconds 100
                }
                
                $statusClient = New-Object System.Net.WebClient
                $statusClient.Encoding = [System.Text.Encoding]::UTF8
                $statusClient.Headers.Add("Authorization", "Bearer $UM_BEARER_TOKEN")
                
                $statusUrl = "$UM_BASE_URL/RA/LIVERPOOL/getExecutionUM?idExecution=$jobId"
                $statusText = $statusClient.DownloadString($statusUrl)
                
                # REGLA: Verificar si los datos no pudieron ser verificados
                if ($statusText -match "Tus datos no han podido ser verificados") {
                    $progressBar.Visible = $false
                    $lblProgress.Visible = $false
                    $form.Cursor = [System.Windows.Forms.Cursors]::Default
                    Write-AuditLog -Status "FALLA" -Action $actionVal -TargetUser $txtUsuario.Text -TargetApp $cmbApp.SelectedItem -Detail "Datos no verificados"
                    &$script:UpdateStatus "La solicitud no pudo ser completada ya que los datos de seguridad introducidos no son correctos." "Error"
                    $completed = $true
                    break
                }

                $statusResp = $statusText | ConvertFrom-Json
                $execData = $statusResp.result.execution
            
                if ($null -ne $execData) {
                    if ($execData.status -eq "success") {
                        # Lanzar polleo a AppScript para estado final
                        $ticketId = $execData.incident
                        $appToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"
                        $appScriptUrl = "https://script.google.com/macros/s/AKfycbw6XKI0IWXPZdQHGhJp4k84BGrKaL9zJjrhjIsyGoK4DU5T-y5Qetx7-Cpgrr-C_p1P/exec?dwp_srid=$ticketId&api_key=$appToken"
                        
                        $lblProgress.Text = "⏳ Validando estado en Mesa de Servicio..."
                        $form.Update()

                        # Polling AppScript (9 intentos cada 10s = 1.5 min)
                        for ($j = 0; $j -lt 9; $j++) {
                            try {
                                $appClient = New-Object System.Net.WebClient
                                $appClient.Encoding = [System.Text.Encoding]::UTF8
                                $appText = $appClient.DownloadString($appScriptUrl)
                                $appResp = $appText | ConvertFrom-Json
                                
                                # Escenario 1: Éxito
                                if ($appResp.status -eq "Completed") {
                                    $progressBar.Value = 100
                                    $lblProgress.Text = "✅ ¡Éxito!"
                                    $form.Update()
                                    Start-Sleep -Milliseconds 500
                                    $progressBar.Visible = $false
                                    $lblProgress.Visible = $false
                                    $form.Cursor = [System.Windows.Forms.Cursors]::Default
                                    
                                    $successMsg = "El reinicio de contraseña se realizó de manera exitosa. La contraseña fue enviada al correo electrónico del usuario. Ticket: $($appResp.workOrderId)"
                                    Write-AuditLog -Status "EXITO" -Action $actionVal -TargetUser $txtUsuario.Text -TargetApp $cmbApp.SelectedItem -Detail $successMsg
                                    &$script:UpdateStatus $successMsg "Success"
                                    $completed = $true
                                    break
                                }
                                # Escenario 2: Asignado a Mesa de Servicios
                                elseif ($appText -match "Estimada mesa de servicio fue asignado a su grupo la solicitud.") {
                                    $lblProgress.Text = "❌ Asignado a Mesa de Servicio."
                                    $form.Update()
                                    Start-Sleep -Milliseconds 500
                                    $progressBar.Visible = $false
                                    $lblProgress.Visible = $false
                                    $form.Cursor = [System.Windows.Forms.Cursors]::Default
                                    
                                    $failMsg = "El reinicio de contraseña no pudo ser realizado. El ticket $($appResp.workOrderId) fue asignado a mesa de servicios."
                                    Write-AuditLog -Status "FALLA" -Action $actionVal -TargetUser $txtUsuario.Text -TargetApp $cmbApp.SelectedItem -Detail $failMsg
                                    &$script:UpdateStatus $failMsg "Error"
                                    $completed = $true
                                    break
                                }
                            }
                            catch {
                                # Si falla el get, reintentar
                            }
                            
                            # Espera entre intentos de AppScript
                            $waitEndTime2 = (Get-Date).AddSeconds(10)
                            while ((Get-Date) -lt $waitEndTime2) {
                                [System.Windows.Forms.Application]::DoEvents()
                                Start-Sleep -Milliseconds 200
                            }
                        }
                        
                        if ($completed) { break }
                    }
                    elseif ($execData.status -eq "failed") {
                        $lblProgress.Text = "❌ La solicitud falló en UM."
                        $form.Update()
                        Start-Sleep -Milliseconds 500
                        $progressBar.Visible = $false
                        $lblProgress.Visible = $false
                        $form.Cursor = [System.Windows.Forms.Cursors]::Default
                        $errDetail = $execData.detail
                        if ([string]::IsNullOrWhiteSpace($errDetail)) { $errDetail = "Error en el Robot Assistant" }
                    
                        Write-AuditLog -Status "FALLA" -Action $actionVal -TargetUser $txtUsuario.Text -TargetApp $cmbApp.SelectedItem -Detail $errDetail
                        &$script:UpdateStatus "FALLÓ:`nDetalle: $errDetail" "Error"
                        $completed = $true
                        break
                    }
                }
            }

            if (-not $completed) {
                $lblProgress.Text = "⚠️ Tiempo de espera agotado."
                $form.Update()
                Start-Sleep -Milliseconds 500
                $progressBar.Visible = $false
                $lblProgress.Visible = $false
                $form.Cursor = [System.Windows.Forms.Cursors]::Default
                Write-AuditLog -Status "TIMEOUT" -Action $actionVal -TargetUser $txtUsuario.Text -TargetApp $cmbApp.SelectedItem -Detail "Sin respuesta de UM"
                &$script:UpdateStatus "TIMEOUT: Han pasado 5 minutos y el sistema no reportó un estado final." "Warning"
            }

            # Limpiar formulario tras el éxito para nueva captura
            $txtUsuario.Text = ""
            $txtEmpleado.Text = ""
            $txtCorreo.Text = ""
            $txtRFC.Text = ""
            $cmbApp.SelectedIndex = 0

        }
        catch {
            $errMessage = $_.Exception.Message
            if ($_.Exception.Response) {
                try {
                    $errStream = $_.Exception.Response.GetResponseStream()
                    $reader = New-Object System.IO.StreamReader($errStream)
                    $errBody = $reader.ReadToEnd()
                    $errMessage += "`n[Respuesta del Servidor]: $errBody"
                }
                catch { }
            }
            
            $act = if ($cmbAccion.SelectedItem) { $cmbAccion.SelectedItem } else { "N/A" }
            $usr = if ($txtUsuario.Text) { $txtUsuario.Text } else { "N/A" }
            $app = if ($cmbApp.SelectedItem) { $cmbApp.SelectedItem } else { "N/A" }
            Write-AuditLog -Status "ERROR_RED" -Action $act -TargetUser $usr -TargetApp $app -Detail $errMessage.Replace("`n", " | ")
            
            $progressBar.Visible = $false
            $lblProgress.Visible = $false
            $form.Cursor = [System.Windows.Forms.Cursors]::Default
            &$script:UpdateStatus "CRITICAL ERROR:`n$errMessage" "Error"
        }

        $btnSubmit.Enabled = $true
        $gbDatos.Enabled = $true
        $gbSolicitud.Enabled = $true
        $progressBar.Visible = $false
        $lblProgress.Visible = $false
        $progressBar.Value = 0
        $form.Cursor = [System.Windows.Forms.Cursors]::Default
        $btnSubmit.Text = "Enviar Solicitud"
    })

# Lanzar
$form.ShowDialog() | Out-Null
